import sys, os, json
import pandas as pd
import numpy as np
import scipy.stats as stats
import statsmodels.api as sm
import pingouin as pg
import matplotlib.pyplot as plt
import seaborn as sns

# Setup
output_dir = os.path.join('/Users/eduardbelskih/Проекты Github/statproject/backend', 'backend', 'output')
os.makedirs(output_dir, exist_ok=True)
results = { "analyses": [], "plots": [], "errors": [] }

try:
    # Load
    path = '/Users/eduardbelskih/Проекты Github/statproject/backend/workspace/covid19_dataset.csv'
    if path.endswith('.csv'): df = pd.read_csv(path)
    elif path.endswith('.parquet'): df = pd.read_parquet(path)
    elif path.endswith('.xlsx'): df = pd.read_excel(path)
    else: raise ValueError("Unknown format")

    # Plan Execution
    plan = {
  "understood_goal": "A professional statistical analysis of COVID-19 patient data, focusing on descriptive statistics for key demographic and hospitalization variables, and a comparative analysis between discharged and deceased patients based on age, initial SpO2, and WBC count, utilizing t-tests and Cohen's d for effect size.",
  "domain": "Medical",
  "warnings": [
    "The dataset contains a large number of columns (159), many of which may have missing values or require extensive cleaning and feature engineering. The current plan focuses only on the variables explicitly requested.",
    "Column names are in Russian, which will require careful handling to ensure correct variable identification and interpretation.",
    "The 'Исход' column (Outcome) will be used as the primary grouping variable for comparisons. It's assumed to clearly distinguish between 'выписан' (discharged) and 'умер' (deceased)."
  ],
  "design": {
    "study_type": "cross_sectional",
    "group_col": "Исход",
    "target_col": null,
    "id_col": "ID",
    "time_col": null
  },
  "analyses": [
    {
      "name": "Описательная статистика по демографическим данным и длительности госпитализации",
      "type": "descriptive",
      "variables": [
        "возраст",
        "пол",
        "Длительность госпитализации"
      ],
      "group_by": null,
      "description": "Расчет основных описательных статистик (среднее, медиана, стандартное отклонение, мин/макс, частоты) для возраста, пола и длительности госпитализации."
    },
    {
      "name": "Сравнение возраста между выписанными и умершими пациентами",
      "type": "t_test",
      "variables": [
        "возраст"
      ],
      "group_by": "Исход",
      "description": "Сравнение среднего возраста между группами пациентов с исходом 'выписан' и 'умер' с использованием независимого t-теста. Будет рассчитан Cohen's d для оценки размера эффекта."
    },
    {
      "name": "Сравнение SpO2 при поступлении между выписанными и умершими пациентами",
      "type": "t_test",
      "variables": [
        "SpO2 %"
      ],
      "group_by": "Исход",
      "description": "Сравнение среднего уровня SpO2 при поступлении между группами пациентов с исходом 'выписан' и 'умер' с использованием независимого t-теста. Будет рассчитан Cohen's d для оценки размера эффекта."
    },
    {
      "name": "Сравнение лейкоцитов (WBC V1) между выписанными и умершими пациентами",
      "type": "t_test",
      "variables": [
        "WBC V1 10*9"
      ],
      "group_by": "Исход",
      "description": "Сравнение среднего уровня лейкоцитов (WBC V1) при поступлении между группами пациентов с исходом 'выписан' и 'умер' с использованием независимого t-теста. Будет рассчитан Cohen's d для оценки размера эффекта."
    }
  ],
  "corrections": "none",
  "effect_sizes": true,
  "confidence_level": 0.95,
  "language": "ru"
}

    for item in plan.get("analyses", []):
        res_item = { "name": item["name"], "type": item["type"], "data": {} }
        try:
            if item["type"] == "descriptive":
                # Descriptive Statistics
                desc_stats = {}
                for var in item["variables"]:
                    if var in df.columns:
                        desc_stats[var] = {
                            "mean": df[var].mean(),
                            "median": df[var].median(),
                            "std": df[var].std(),
                            "min": df[var].min(),
                            "max": df[var].max()
                        }
                        if var == "пол":
                            desc_stats[var]["frequencies"] = df[var].value_counts().to_dict()
                    else:
                        results["errors"].append(f"Column {var} not found for analysis {item['name']}")
                res_item["data"] = desc_stats

            elif item["type"] == "t_test":
                # T-Test and Cohen's d
                for var in item["variables"]:
                    if var in df.columns and item["group_by"] in df.columns:
                        df_clean = df[[var, item["group_by"]]].dropna()
                        groups = df_clean[item["group_by"]].unique()
                        if len(groups) == 2:
                            group1 = df_clean[df_clean[item["group_by"]] == groups[0]][var]
                            group2 = df_clean[df_clean[item["group_by"]] == groups[1]][var]
                            t_stat, p_val = stats.ttest_ind(group1, group2)
                            cohen_d = pg.compute_effsize(group1, group2, eftype='cohen')
                            res_item["data"][var] = {
                                "t_statistic": t_stat,
                                "p_value": p_val,
                                "cohen_d": cohen_d
                            }
                        else:
                            results["errors"].append(f"Grouping column {item['group_by']} does not have exactly 2 unique values for analysis {item['name']}")
                    else:
                        results["errors"].append(f"Column {var} or {item['group_by']} not found for analysis {item['name']}")

            # Save Plots
            if item["type"] == "t_test" and item["group_by"] in df.columns:
                for var in item["variables"]:
                    if var in df.columns:
                        plt.figure()
                        sns.boxplot(x=item["group_by"], y=var, data=df)
                        plot_path = os.path.join(output_dir, f"{item['name']}_{var}.png")
                        plt.savefig(plot_path)
                        plt.close()
                        results["plots"].append(plot_path)

        except Exception as e:
            results["errors"].append(f"Analysis {item['name']} failed: {str(e)}")

        results["analyses"].append(res_item)

except Exception as e:
    results["errors"].append(f"Critical Pipeline Error: {str(e)}")

# FINAL OUTPUT
print("<JSON_START>")
print(json.dumps(results, default=str, ensure_ascii=False))
print("<JSON_END>")
